const qk=k=>{const d=new Date(),y=d.getFullYear(),m=d.getMonth(),f=x=>x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0');if(k==='w'){const s=new Date(d);s.setDate(d.getDate()-((d.getDay()+6)%7));return{a:f(s),b:f(d),k}}if(k==='l')return{a:f(new Date(y,m-1,1)),b:f(new Date(y,m,0)),k};return{a:f(new Date(y,m,1)),b:f(d),k:'m'}};
function lrows(){const p=S.lp=S.lp||qk('m'),a=Date.parse(p.a),b=Date.parse(p.b)+864e5;return S.d.requests.filter(x=>{const t=Date.parse(x.at);return t>=a&&t<b})}
