function fEdit(id){const p=S.d.patients.find(x=>x.id===id);mod(mh('edit_note','Ubah Data Registrasi','EDIT / PINDAH RUANGAN')+`<div class="flex flex-col gap-space-sm"><label class="${LB}">Nama lengkap<input id="e1" class="${IN}" value="${E(p.nama)}"></label><label class="${LB}">No MR<input id="e2" class="${IN}" value="${E(p.mr)}"></label><div class="grid grid-cols-2 gap-space-sm"><label class="${LB}">Ruangan<select id="e3" class="${IN}">${['Lt 5','Lt 6','HCU'].map(x=>`<option ${x===p.lantai?'selected':''}>${x}</option>`).join('')}</select></label><label class="${LB}">Kamar / bed<input id="e4" class="${IN}" value="${E(p.kamar)}"></label></div><label class="${LB}">Asuransi<input id="e5" list="dl2" class="${IN}" value="${E(p.asuransi)}"></label><datalist id="dl2">${S.d.master.map(a=>`<option value="${E(a)}">`).join('')}</datalist><label class="${LB}">Catatan serah terima (jika pindah ruangan)<textarea id="e6" class="${IN} h-20"></textarea></label><p class="font-body-sm text-body-sm text-on-surface-variant m-0">Perubahan dicatat di riwayat. Jika ruangan berubah, RMO lantai lama dan baru diberi tahu.</p></div>`+ft(`<button class="${BO}" onclick="edPat('${id}')" type="button">Simpan</button>`))}
async function edPat(id){const v=i=>$('#e'+i).value;if(!v(1).trim()||!v(2).trim()||!v(5).trim())return toast('Nama, MR, dan asuransi wajib diisi.',1);if(!await ask('Simpan perubahan data pasien?'))return;run(()=>api('patient.edit',{pid:id,nama:v(1),mr:v(2),lantai:v(3),kamar:v(4),asuransi:v(5),catatan:v(6)}),'Data pasien diperbarui.')}
// ---- modal & aksi ----
function mod(h){const m=$('#modal');if(!h){m.hidden=true;m.innerHTML='';return}m.innerHTML='<div class="w-full sm:max-w-lg bg-surface-container-lowest rounded-t-2xl sm:rounded-2xl shadow-xl p-space-lg flex flex-col gap-space-md max-h-[92vh] overflow-y-auto">'+h+'</div>';m.hidden=false;m.onclick=e=>{if(e.target===m)mod()}}
const mh=(ic,t,s,d)=>`<div class="flex items-center justify-between pb-space-sm border-b border-surface-container"><div class="flex items-center gap-2"><div class="w-9 h-9 rounded-xl ${d?'bg-error text-on-error':'bg-primary-container text-on-primary'} flex items-center justify-center"><span class="material-symbols-outlined text-[20px]">${ic}</span></div><div><h3 class="font-headline-sm text-headline-sm ${d?'text-error':'text-primary'} m-0">${t}</h3><span class="font-code-mono text-code-mono text-on-surface-variant text-[11px]">${s}</span></div></div><button class="w-8 h-8 rounded-lg hover:bg-surface-container flex items-center justify-center text-on-surface-variant" onclick="mod()" data-x type="button"><span class="material-symbols-outlined text-[20px]">close</span></button></div>`;
const IN='w-full h-11 px-space-md rounded-xl bg-surface-container-low border-0 font-body-md text-body-md text-on-surface focus:outline-none focus:ring-2 focus:ring-primary-container mt-1',LB='font-label-md text-label-md text-on-surface-variant block',BC='h-11 px-space-md rounded-xl bg-surface-container text-on-surface font-label-md text-label-md hover:bg-surface-container-high',BO='h-11 px-space-md rounded-xl bg-primary-container text-on-primary font-label-md text-label-md hover:bg-primary shadow-md',ft=b=>`<div class="pt-space-sm border-t border-surface-container flex items-center justify-end gap-space-sm"><button class="${BC}" onclick="mod()" type="button">Batal</button>${b}</div>`;
function ask(msg,o={}){return new Promise(ok=>{const c=document.createElement('div');c.className='fixed inset-0 z-[60] flex items-end sm:items-center justify-center p-4';c.style.cssText='background:rgba(15,42,128,.4);backdrop-filter:blur(4px)';c.innerHTML=`<div class="w-full max-w-md bg-surface-container-lowest rounded-2xl shadow-xl p-space-lg flex flex-col gap-space-md">${mh(o.danger?'warning':'help',o.title||'Konfirmasi',o.sub||'KONFIRMASI AKSI',o.danger)}<p class="font-body-md text-body-md text-on-surface m-0">${E(msg)}</p><div class="flex justify-end gap-space-sm"><button class="${BC}" data-n type="button">Batal</button><button class="${o.danger?'h-11 px-space-md rounded-xl bg-error text-on-error font-label-md text-label-md hover:bg-[#B91C1C] shadow-md':BO}" data-y type="button">${o.yes||'Ya, lanjutkan'}</button></div></div>`;document.body.appendChild(c);const d=v=>{c.remove();ok(v)};c.querySelector('[data-y]').onclick=()=>d(true);c.querySelector('[data-n]').onclick=()=>d(false);c.querySelector('[data-x]').onclick=()=>d(false)})}
function fPat(){mod(mh('person_add','Registrasi Pasien','REGISTRASI PASIEN BARU')+`<div class="flex flex-col gap-space-sm"><label class="${LB}">Nama lengkap<input id="a1" class="${IN}"></label><label class="${LB}">No MR<input id="a2" class="${IN}"></label><div class="grid grid-cols-2 gap-space-sm"><label class="${LB}">Ruangan<select id="a3" class="${IN}"><option>Lt 5</option><option>Lt 6</option><option>HCU</option></select></label><label class="${LB}">Kamar / bed<input id="a4" class="${IN}" placeholder="Opsional"></label></div><label class="${LB}">Asuransi<input id="a5" list="dl" class="${IN}"></label><datalist id="dl">${(S.d.master.length?S.d.master:[...new Set(S.d.patients.map(p=>p.asuransi))]).map(a=>`<option value="${E(a)}">`).join('')}</datalist></div>`+ft(`<button class="${BO}" onclick="addPat()" type="button">Simpan</button>`))}
async function addPat(){const v=i=>$('#a'+i).value;if(!v(1).trim()||!v(2).trim()||!v(5).trim())return toast('Nama, MR, dan asuransi wajib diisi.',1);if(!await ask('Simpan pasien '+v(1)+'?'))return;run(()=>api('patient.add',{nama:v(1),mr:v(2),lantai:v(3),kamar:v(4),asuransi:v(5)}),'Pasien ditambahkan.')}
function fReq(pid){mod(mh('note_add','Buat Permintaan Berkas','PERMINTAAN LMA / LML')+`<div class="flex flex-col gap-space-sm"><label class="${LB}">Jenis<select id="r1" class="${IN}"><option>LMA</option><option>LML</option></select></label><label class="${LB}">Tanggal layanan<input id="r2" type="date" class="${IN}"></label><label class="${LB}">Catatan kekurangan<textarea id="r3" class="${IN} h-24"></textarea></label><label class="${LB}">Tenggat (opsional)<input id="r4" type="datetime-local" class="${IN}"></label></div>`+ft(`<button class="${BO}" onclick="addReq('${pid}')" type="button">Simpan</button>`))}
function addReq(pid){if(!$('#r2').value)return toast('Tanggal layanan wajib diisi.',1);run(()=>api('request.add',{pid,jenis:$('#r1').value,tanggal:$('#r2').value,catatan:$('#r3').value,due:$('#r4').value}),'Permintaan berkas dibuat.')}
function fUp(rid,act,t){mod(mh('upload_file',t,'UNGGAH BERKAS')+`<label class="flex flex-col items-center justify-center gap-space-xs p-space-lg rounded-xl border-2 border-dashed border-outline-variant bg-surface-container-low text-center cursor-pointer"><span class="material-symbols-outlined text-[32px] text-primary-container">cloud_upload</span><span class="font-label-lg text-label-lg text-on-surface">Pilih file</span><input id="f1" type="file" class="!border-0 !min-h-0 text-[12px]"><span class="font-body-sm text-body-sm text-on-surface-variant">PDF, DOC, DOCX, XLS, XLSX, CSV, TXT, JPG, PNG · maks 8 MB</span></label>`+ft(`<button class="${BO}" onclick="up('${rid}','${act}')" type="button">Upload</button>`))}
async function up(rid,act){const f=$('#f1').files[0];if(!f)return toast('Pilih file terlebih dahulu.',1);if(f.size>8388608)return toast('Ukuran file maksimal 8 MB.',1);if(!await ask('Upload '+f.name+'?'))return;
 const r=new FileReader();r.onload=()=>run(()=>api(act,{rid,name:f.name,mime:f.type,b64:r.result.split(',')[1]}),'Berhasil diupload.');r.readAsDataURL(f)}
async function dl(rid,kind){if(kind==='rmo'&&isFO()&&!await ask('Unduh jawaban RMO? Waktu unduh akan dicatat dan RMO diberi tahu.'))return;
 const j=await run(()=>api('doc.get',{rid,kind}));if(!j||!j.file)return;const b=atob(j.file.b64),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);
 const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([u],{type:j.file.mime}));a.download=j.file.name;a.click()}
async function disch(id){const o=S.d.requests.filter(x=>x.pid===id&&x.st!=='SELESAI').length;if(await ask((o?'Peringatan: pasien memiliki '+o+' berkas yang belum selesai. ':'')+'Pasien akan hilang dari daftar aktif dan masuk Arsip. Data tidak dihapus.',{danger:1,title:'Konfirmasi Discharge',sub:'DISCHARGE AUTHORIZATION',yes:'Ya, Discharge'}))run(async()=>{const r=await api('patient.discharge',{pid:id});location.hash='#/pts';return r},'Pasien di-discharge.')}
$('#bell').onclick=e=>{e.stopPropagation();const p=$('#np');if(!p.hidden){p.hidden=true;return}p.innerHTML=`<div class="flex items-center justify-between p-space-md border-b border-surface-container"><div class="flex items-center gap-space-xs"><span class="material-symbols-outlined text-primary">notifications_active</span><h3 class="font-headline-sm text-headline-sm text-primary m-0">Pusat Notifikasi</h3></div><button onclick="rdAll()" class="font-label-md text-label-md text-primary-container" type="button">Tandai semua dibaca</button></div><div class="max-h-[60vh] overflow-y-auto p-space-sm flex flex-col gap-1">${S.d.notifs.map(x=>`<div onclick="$('#np').hidden=true;location.hash='#/p/${x.pid}'" class="cursor-pointer p-space-sm rounded-xl ${x.rd?'bg-surface-container-lowest':'bg-surface-container-low'} hover:bg-surface-container transition-colors"><div class="flex items-center justify-between"><span class="font-label-md text-label-md ${x.rd?'text-on-surface-variant':'text-primary'}">${x.rd?'':'● '}${E(x.t)}</span><span class="font-code-mono text-[11px] text-on-surface-variant">${fmt(x.at)}</span></div><p class="font-body-sm text-body-sm text-on-surface mt-1 m-0">${E(x.m)}</p></div>`).join('')||'<p class="p-space-md text-on-surface-variant">Belum ada notifikasi.</p>'}</div>`;p.hidden=false};
function rdAll(){api('notif.read').then(()=>{render();$('#np').hidden=true}).catch(e=>toast(e.message,1))}
document.addEventListener('click',e=>{const p=$('#np');if(p&&!p.hidden&&!p.contains(e.target))p.hidden=true});
let wasM=innerWidth<1024;addEventListener('resize',()=>{const m=innerWidth<1024;if(m!==wasM){wasM=m;render()}});
// ---- Sinkronisasi otomatis hemat server ----
// Tiap beberapa detik klien hanya mengirim "ping" super ringan (baca cache). Data penuh diambil HANYA bila versi berubah.
// Berhenti saat tab tersembunyi/modal terbuka/sedang mengetik; melambat saat tidak ada aktivitas; mundur eksponensial bila gagal.
let lastAct=Date.now(),tm=null,fail=0,busyS=false;
['pointerdown','keydown','scroll','touchstart'].forEach(e=>addEventListener(e,()=>{lastAct=Date.now()},{passive:true}));
async function q(a,d={}){const r=await fetch(API,{method:'POST',headers:{'Content-Type':'text/plain'},body:JSON.stringify({action:a,token:S.tok,...d})}),j=await r.json();
 if(!j.ok){if(/Sesi|tidak aktif/.test(j.message))logout();throw new Error(j.message)}if(j.data){S.d=j.data;S.bv=j.v}return j}
const typing=()=>/^(INPUT|TEXTAREA)$/.test((document.activeElement||{}).tagName)&&Date.now()-lastAct<8000;
const setSync=()=>{const t=S.sync?S.sync.toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'}).replace('.',':'):'';document.querySelectorAll('[data-sync]').forEach(e=>e.textContent=t)};
const nextMs=()=>Math.min(POLL.max,(Date.now()-lastAct>POLL.idleAfter?POLL.idle:POLL.active)*Math.pow(2,fail))*(0.8+Math.random()*0.4);
function sched(){clearTimeout(tm);if(S.tok)tm=setTimeout(tick,nextMs())}
async function tick(force){
 if(!S.tok||!S.d||busyS||(!force&&(document.hidden||!$('#modal').hidden||typing())))return sched();
 busyS=true;
 try{const un=S.d.notifs.filter(n=>!n.rd).length,p=await q('ping');
  if(p.v!==S.bv||force===2){await q('boot');const nn=S.d.notifs.filter(n=>!n.rd);if(nn.length>un)toast('\u{1F514} '+nn[0].m);render()}
  fail=0;S.sync=new Date();setSync();$('#stale').hidden=true}
 catch(e){fail++;if(fail>=2)$('#stale').hidden=false;if(force)toast('Gagal menyinkronkan data.',1)}
 finally{busyS=false;sched()}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick(true)});
addEventListener('online',()=>tick(true));addEventListener('offline',()=>{$('#stale').hidden=false});
// Status "terlambat" berubah seiring waktu: render ulang hanya bila himpunan berkas terlambat berubah (cek tiap menit, tanpa jaringan).
setInterval(()=>{if(!S.d||!$('#modal').hidden||typing())return;const g=S.d.requests.filter(late).map(x=>x.id).join();if(S.ls!==undefined&&g!==S.ls)render();S.ls=g},60000);
// ---- boot & penyegaran data (tanpa login ulang) ----
if(S.tok){$('#login').hidden=true;$('#app').hidden=false;$('#v').innerHTML='<div class="sk"></div>';api('boot').then(enter).catch(showLogin)}else showLogin();
